/**
 * Bundles the game's own scoring, level data and route rebuilding into one
 * Deno-friendly module for the submit-run edge function.
 *
 * The function has to score a submitted run with *exactly* the code the client
 * scores with — that is the whole reason the server can be trusted with a
 * total nobody sent it. It cannot simply import `src/game/scoring.ts`, because
 * the app's imports are extensionless and Deno insists on extensions. So the
 * shared surface is bundled here instead, and never edited by hand.
 *
 * Run by `npm run build:club`. The bundle is committed, so it can go stale if
 * someone changes the scoring and forgets — regenerate it before deploying the
 * function, and see the note in the README about guarding that in CI.
 */
import { rolldown } from "rolldown";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const outfile = resolve(root, "supabase/functions/_shared/game.bundle.js");

// Rolldown, because that is what Vite 8 already bundles the app with. No new
// build dependency for this, and no second opinion on how the source resolves.
const bundle = await rolldown({
  input: resolve(root, "src/club/gameSurface.ts"),
  platform: "neutral",
});

await bundle.write({
  file: outfile,
  format: "esm",
  // Readable on purpose: this lands in the repo, and a bundle nobody can read
  // is a bundle nobody notices has gone wrong.
  minify: false,
  banner: [
    "// GENERATED by scripts/build-club-bundle.mjs \u2014 do not edit.",
    "// Source: src/club/gameSurface.ts and everything it imports.",
    "",
  ].join("\n"),
});

await bundle.close();

console.log(`Wrote ${outfile.replace(root + "/", "")}`);
